SELECT (SELECT type FROM sqlite_schema WHERE name='MAIN') AS main_object, (SELECT type FROM sqlite_schema WHERE name='B') AS b_object, (SELECT type FROM sqlite_schema WHERE name='v1') AS v1_object, (SELECT type FROM sqlite_schema WHERE name='v2') AS v2_object, (SELECT count(*) FROM MAIN) AS main_count, (SELECT count(*) FROM MAIN WHERE Id=2 AND Id1=3) AS main_match, (SELECT count(*) FROM B) AS b_count, (SELECT count(*) FROM B WHERE Id=2 AND Id1=3) AS b_match, (SELECT count(*) FROM v1) AS v1_count, (SELECT count(*) FROM v1 WHERE Id=2 AND Id1=3) AS v1_match, (SELECT count(*) FROM v2) AS v2_count, (SELECT count(*) FROM v2 WHERE Id=2 AND Id1=3) AS v2_match;